class_name Entity
extends Node2D
## Base for units, buildings and resource nodes.

var game: Node = null
var team: int = -1 # 0 = player, 1 = computer, -1 = nature
var kind: String = ""
var hp: float = 1.0
var max_hp: float = 1.0
var radius: float = 10.0
var selected: bool = false
var dead: bool = false
var flash: float = 0.0


func is_alive() -> bool:
	return not dead and is_instance_valid(self)


func cls() -> String:
	return "none"


func display_name() -> String:
	return kind


func set_selected(v: bool) -> void:
	selected = v
	queue_redraw()


func take_damage(amount: float, _attacker: Node) -> void:
	if dead:
		return
	hp -= amount
	flash = 0.15
	queue_redraw()
	if hp <= 0.0:
		hp = 0.0
		die()


func die() -> void:
	if dead:
		return
	dead = true
	if game:
		game.on_entity_died(self)
	queue_free()


func draw_hp_bar(y: float, w: float) -> void:
	if max_hp <= 0.0:
		return
	var frac := clampf(hp / max_hp, 0.0, 1.0)
	if frac >= 0.999 and not selected:
		return
	draw_rect(Rect2(-w * 0.5, y, w, 4), Color(0, 0, 0, 0.7))
	var c := Color(0.3, 0.9, 0.3) if frac > 0.5 else (Color(0.95, 0.8, 0.2) if frac > 0.25 else Color(0.95, 0.25, 0.2))
	draw_rect(Rect2(-w * 0.5, y, w * frac, 4), c)

extends Node2D
## Static grass with patches, drawn once.

func _draw() -> void:
	var w := float(DB.MAP_W)
	var h := float(DB.MAP_H)
	draw_rect(Rect2(-2000, -2000, w + 4000, h + 4000), Color(0.07, 0.09, 0.07))
	draw_rect(Rect2(0, 0, w, h), Color(0.36, 0.55, 0.25))
	var r := RandomNumberGenerator.new()
	r.seed = 77
	for i in 900:
		var p := Vector2(r.randf() * w, r.randf() * h)
		var c := Color(0.36, 0.55, 0.25).lerp(Color(0.3, 0.47, 0.2) if r.randf() < 0.5 else Color(0.45, 0.62, 0.3), r.randf_range(0.3, 0.9))
		draw_circle(p, r.randf_range(20, 70), c)
	for i in 120:
		var p := Vector2(r.randf() * w, r.randf() * h)
		draw_circle(p, r.randf_range(14, 40), Color(0.5, 0.45, 0.3, 0.55))
	for i in 2500:
		var p := Vector2(r.randf() * w, r.randf() * h)
		draw_line(p, p + Vector2(r.randf_range(-2, 2), -5), Color(0.25, 0.42, 0.18, 0.7), 1.0)
	# dirt around the two starting sites
	for c in [Vector2(512, 2048), Vector2(w - 512, h - 2048)]:
		for i in 26:
			draw_circle(c + Vector2(r.randf_range(-120, 120), r.randf_range(-110, 110)), r.randf_range(30, 60), Color(0.55, 0.48, 0.32, 0.45))
	draw_rect(Rect2(0, 0, w, h), Color(0.05, 0.07, 0.05), false, 6.0)

extends Control
## Small overview map; touch or drag on it to move the camera.

var game: Node = null
var pings: Array = []
var dragging: bool = false


func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_STOP
	clip_contents = true


func ping(world_pos: Vector2) -> void:
	pings.append({"p": world_pos, "t": 3.0})


func _scale() -> Vector2:
	return size / Vector2(DB.MAP_W, DB.MAP_H)


func _gui_input(ev: InputEvent) -> void:
	if game == null:
		return
	var pos := Vector2(-1, -1)
	if ev is InputEventMouseButton and ev.button_index == MOUSE_BUTTON_LEFT:
		dragging = ev.pressed
		if ev.pressed:
			pos = ev.position
	elif ev is InputEventMouseMotion and dragging:
		pos = ev.position
	elif ev is InputEventScreenTouch and ev.pressed:
		pos = ev.position - global_position
	elif ev is InputEventScreenDrag:
		pos = ev.position - global_position
	if pos.x >= 0.0:
		game.center_on(pos / _scale())
		accept_event()


func _process(delta: float) -> void:
	for i in range(pings.size() - 1, -1, -1):
		pings[i]["t"] -= delta
		if pings[i]["t"] <= 0.0:
			pings.remove_at(i)


func _draw() -> void:
	if game == null:
		return
	var sc := _scale()
	draw_rect(Rect2(Vector2.ZERO, size), Color(0.22, 0.36, 0.16))
	for n in game.resources:
		if n.dead:
			continue
		var c: Color = Color(0.1, 0.3, 0.1) if n.kind == "tree" else DB.RES_COLORS[n.res]
		draw_rect(Rect2(n.position * sc - Vector2(1, 1), Vector2(2, 2)), c)
	for b in game.buildings:
		if b.dead:
			continue
		var r := Rect2(b.rect().position * sc, b.rect().size * sc)
		r.size = r.size.max(Vector2(3, 3))
		draw_rect(r, DB.TEAM_COLORS[b.team].lightened(0.2))
	for u in game.units:
		if u.dead:
			continue
		draw_rect(Rect2(u.position * sc - Vector2(1.5, 1.5), Vector2(3, 3)), DB.TEAM_COLORS[u.team].lightened(0.35))
	for p in pings:
		var a: float = p["t"] / 3.0
		draw_arc(p["p"] * sc, 4.0 + 10.0 * (1.0 - fmod(p["t"], 1.0)), 0, TAU, 16, Color(1, 0.3, 0.2, a), 2.0)
	# camera view
	var vp := get_viewport().get_visible_rect().size
	if game.camera:
		var vs: Vector2 = vp / game.camera.zoom
		var tl: Vector2 = game.camera.position - vs * 0.5
		draw_rect(Rect2(tl * sc, vs * sc), Color(1, 1, 1, 0.9), false, 1.5)
	draw_rect(Rect2(Vector2.ZERO, size), Color(0.75, 0.6, 0.3), false, 2.0)

extends Node
## Entry point: main menu, starting/restarting matches, --screenshot and --self-test.

var game: Node2D = null
var hud: CanvasLayer = null
var menu: CanvasLayer = null
var difficulty: String = "Normal"
var shot_path: String = ""
var test_path: String = ""
var frames: int = 0
var shooting: bool = false


func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	var args: Array = []
	args.append_array(OS.get_cmdline_args())
	args.append_array(OS.get_cmdline_user_args())
	for i in args.size():
		var a: String = args[i]
		if a == "--screenshot" and i + 1 < args.size():
			shot_path = args[i + 1]
		elif a.begins_with("--screenshot="):
			shot_path = a.substr(13)
		elif a == "--self-test" and i + 1 < args.size():
			test_path = args[i + 1]
		elif a.begins_with("--self-test="):
			test_path = a.substr(12)
	shot_path = _absolute(shot_path)
	test_path = _absolute(test_path)
	if shot_path != "" or test_path != "":
		DisplayServer.window_set_flag(DisplayServer.WINDOW_FLAG_NO_FOCUS, true)
		start_game("Normal")
		if test_path != "":
			var t: Node = load("res://scripts/selftest.gd").new()
			add_child(t)
			t.run(self, test_path)
		elif shot_path != "":
			_stage_screenshot()
	else:
		show_menu()


func _absolute(p: String) -> String:
	if p == "" or p.is_absolute_path() or p.begins_with("res://") or p.begins_with("user://"):
		return p
	var cwd := OS.get_environment("PWD")
	if cwd == "":
		cwd = ProjectSettings.globalize_path("res://")
	return cwd.path_join(p)


func _process(_delta: float) -> void:
	if shot_path == "" or test_path != "" or shooting:
		return
	frames += 1
	if frames >= 120:
		shooting = true
		_capture()


func _stage_screenshot() -> void:
	# a lively first view: villagers at work, the player's town selected
	Engine.time_scale = 3.0
	var vills: Array = game.units_of(0, true)
	var tree: Entity = game.find_resource_near(vills[0].position, "tree", 900.0, 0)
	var berries: Entity = game.find_resource_near(vills[0].position, "berries", 900.0, 0)
	if berries:
		game.command_gather(vills.slice(0, 2), berries)
	if tree:
		game.command_gather(vills.slice(2, 4), tree)
	game.select(vills)


func _capture() -> void:
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	DirAccess.make_dir_recursive_absolute(shot_path.get_base_dir())
	var err := img.save_png(shot_path)
	if err != OK:
		push_error("could not save screenshot: %s" % error_string(err))
	get_tree().quit()


func _clear() -> void:
	get_tree().paused = false
	Engine.time_scale = 1.0 if test_path == "" and shot_path == "" else Engine.time_scale
	for n in [game, hud, menu]:
		if n != null and is_instance_valid(n):
			n.queue_free()
	game = null
	hud = null
	menu = null


func start_game(diff: String) -> void:
	_clear()
	difficulty = diff
	game = Node2D.new()
	game.set_script(load("res://scripts/game.gd"))
	add_child(game)
	game.setup(diff, null)
	hud = CanvasLayer.new()
	hud.set_script(load("res://scripts/hud.gd"))
	add_child(hud)
	hud.setup(game, self)
	game.hud = hud
	hud.message("Destrua o Centro da Cidade inimigo!", 4.0)


func restart() -> void:
	start_game(difficulty)


func show_menu() -> void:
	_clear()
	menu = CanvasLayer.new()
	menu.set_script(load("res://scripts/menu.gd"))
	add_child(menu)
	menu.setup(self)

